#' Industrial Agglomeration
#'
#' 
#' @param data .
#' @param region .
#' @param industry .
#' @param value .
#' @param firms .
#' @param showRegion .
#' @param sortBy .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$industryTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$regionTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$saveLQ} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$industryTable$asDF}
#'
#' \code{as.data.frame(results$industryTable)}
#'
#' @export
agg <- function(
    data,
    region,
    industry,
    value,
    firms,
    showRegion = TRUE,
    sortBy = "gamma",
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("agg requires jmvcore to be installed (restart may be required)")

    if ( ! missing(region)) region <- jmvcore::resolveQuo(jmvcore::enquo(region))
    if ( ! missing(industry)) industry <- jmvcore::resolveQuo(jmvcore::enquo(industry))
    if ( ! missing(value)) value <- jmvcore::resolveQuo(jmvcore::enquo(value))
    if ( ! missing(firms)) firms <- jmvcore::resolveQuo(jmvcore::enquo(firms))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(region), region, NULL),
            `if`( ! missing(industry), industry, NULL),
            `if`( ! missing(value), value, NULL),
            `if`( ! missing(firms), firms, NULL))


    options <- aggOptions$new(
        region = region,
        industry = industry,
        value = value,
        firms = firms,
        showRegion = showRegion,
        sortBy = sortBy,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- aggClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

